  for(let i=0;i<n;i++){const {exploration:x}=runExplorationCampaign(config),rooms=x.map.rooms.filter(r=>r.depth>0),hands=x.events.filter(e=>e.type==='OVERLORD_HAND'),picks=x.events.filter(e=>e.type==='ROOM_TILE_SELECTED'),ages={};out.audit.checks+=x.audit.checks;out.audit.violations+=x.audit.violations.length;rooms.forEach((room,j)=>{const hand=hands[j].tilesInHand.map(id=>values[id]);for(const t of hand)if(ages[t.id]===undefined)ages[t.id]=0;const expired=maxTileAge===null?[]:hand.filter(t=>ages[t.id]>=maxTileAge),choices=expired.length?expired:hand,score=t=>t.pressureValue-t.futureChoiceValue,max=Math.max(...choices.map(score)),eligible=policy==='LINEAR'?choices.filter(t=>score(t)===max):paretoBalancedValues(choices),eligibleIds=new Set(eligible.map(t=>t.id)),selected=values[picks[j].selectedTileId],burden=hand.filter(t=>t.id==='E2-01'||t.id==='E2-03').length,s=ageStats[selected.id],forced=expired.length>0;out.handCompression.decisions[burden]++;out.handCompression.averageBurdenSlots+=burden;out.rooms++;out.selectedPV+=selected.pressureValue;out.selectedFuturePressure+=selected.minExitFighters;s.plays++;s.ageAtPlay[Math.min(3,ages[selected.id])]++;s.playDepth[j]++;if(forced){s.ageingForcedPlays++;out.ageingForcedPlays++}if(selected.id==='E2-01'||selected.id==='E2-03')out.breathRooms++;if(!eligibleIds.has(selected.id))out.audit.policyViolations++;for(const t of hand)if(t.id!==selected.id){ages[t.id]++;if(maxTileAge!==null&&ages[t.id]===maxTileAge)ageStats[t.id].arrivalsAtMaxAge++}delete ages[selected.id]})}
