function threatAggregate(n=1000,chestPolicy='OPEN_ALL'){const config=clone(EXPLORATION_CONFIG_THREAT_V01);config.threatSystem.chestPolicy=chestPolicy;const out={campaigns:n,chestPolicy,completionRate:0,treasure:{found:0,opened:0,left:0,riskAcceptance:0,tiers:{BRONZE:0,SILVER:0,GOLD:0}},threat:{SAFE:0,AMBUSH:0,ENRAGE:0,bagRefills:0},enrage:{averageFinal:0,byDepth:Array.from({length:config.maxRoomsExplored},()=>({samples:0,average:0})),miniBossUnlockDepth:null,bossUnlockDepth:null,chestsBeforeMiniBoss:null,chestsBeforeBoss:null},ambush:{fighters:0,wipes:0,deaths:{warrior:0,healer:0}},audit:{checks:0,violations:0}};let completed=0,finalEnrage=0;for(let i=0;i<n;i++){const {game:g,exploration:x}=runExplorationCampaign(config),t=x.threatTelemetry;if(g.state==='lost'&&x.activeAmbush){t.ambushWipes++;for(const role of ['warrior','healer'])if(g.party.find(h=>h.role===role).hp<=0)t.ambushDeaths[role]++}completed+=g.telemetry.completion?1:0;finalEnrage+=x.dungeonEnrage;out.treasure.found+=t.treasureFound;out.treasure.opened+=t.treasureOpened;out.treasure.left+=t.treasureLeft;for(const tier of Object.keys(out.treasure.tiers))out.treasure.tiers[tier]+=t.treasureTiers[tier];for(const type of Object.keys(out.threat).filter(k=>k!=='bagRefills'))out.threat[type]+=t.draws[type];out.threat.bagRefills+=x.threatBag.refillCount;out.ambush.fighters+=t.ambushFighters;out.ambush.wipes+=t.ambushWipes;for(const role of ['warrior','healer'])out.ambush.deaths[role]+=t.ambushDeaths[role];x.map.rooms.filter(r=>r.depth>0&&r.treasureResolved).forEach(r=>{const d=out.enrage.byDepth[r.depth-1];d.samples++;d.average+=t.enrageByDepth[r.depth-1]});out.audit.checks+=x.audit.checks;out.audit.violations+=x.audit.violations.length}out.completionRate=completed/n;out.treasure.riskAcceptance=out.treasure.found?out.treasure.opened/out.treasure.found:0;out.enrage.averageFinal=finalEnrage/n;for(const d of out.enrage.byDepth)if(d.samples)d.average/=d.samples;return out}
