function t5Overall(categories){const out={pairs:0,A:{clears:0,rounds:0,endHp:{warrior:0,healer:0},healing:{warrior:0,self:0},deaths:{warrior:0,healer:0}},B:{clears:0,rounds:0,endHp:{warrior:0,healer:0},healing:{warrior:0,self:0},deaths:{warrior:0,healer:0},aoeUses:0}};for(const bucket of Object.values(categories)){out.pairs+=bucket.pairs;for(const label of ['A','B']){const source=bucket[label],target=out[label];target.clears+=source.clears;target.rounds+=source.rounds;for(const role of ['warrior','healer']){target.endHp[role]+=source.endHp[role]*bucket.pairs;target.deaths[role]+=source.deaths[role]}for(const key of ['warrior','self'])target.healing[key]+=source.healing[key]*bucket.pairs;if(label==='B')target.aoeUses+=source.aoeUses}}for(const label of ['A','B']){const target=out[label];target.clearRate=target.clears/out.pairs;target.averageRounds=target.rounds/out.pairs;for(const role of ['warrior','healer'])target.endHp[role]/=out.pairs;for(const key of ['warrior','self'])target.healing[key]/=out.pairs}out.B.aoeUsesPerRoom=out.B.aoeUses/out.pairs;out.delta={clearRate:out.B.clearRate-out.A.clearRate,rounds:out.B.averageRounds-out.A.averageRounds,endHp:{warrior:out.B.endHp.warrior-out.A.endHp.warrior,healer:out.B.endHp.healer-out.A.endHp.healer},healing:{warrior:out.B.healing.warrior-out.A.healing.warrior,self:out.B.healing.self-out.A.healing.self}};return out}
